# CSME Detection report sensor
# Version = 1.0
# TAM - Laurent Chappe 20201005

import tanium
import os
import sys
import tempfile
import xml.etree.ElementTree as ET

#Create list where we will store the filenames found
files = []


def find_CSME_reports():
    #print (tempfile.gettempdir())
    suffix = ".xml"
    prefix = "CSME-Version-Detection-Tool-"

    #Slice the file found in 3 part (r)oot, (d)irectory and (f)ilename
    for r, d, f in os.walk(tempfile.gettempdir()):
        for file in f:
            if file.endswith(suffix) & file.startswith(prefix): 
                files.append(os.path.join(r, file)) #rebuild full file name in list created earlier

    return files


def sensor_main():
    files=find_CSME_reports()

    #Making sensor return a nice message based on OS if nothing found             
    if not files:
        if sys.platform.startswith('win32'):
            tanium.results.add("No Intel CSME scan file found - Windows") 
        elif sys.platform.startswith('linux'):
            tanium.results.add("No Intel CSME scan file found - Linux")
        elif sys.platform.startswith('darwin'):
            tanium.results.add("No Intel CSME scan file found - MacOS")
    else:
        for f in files:
            tree = ET.parse(f)
            root = tree.getroot()

            output = []

            for entry in root.findall("*"):
                output.append(entry.text)
            for entry in root.findall("*/*"):
                output.append(entry.text)

            result=output[1]+"|"+output[3]+"|"+output[7]+"|"+output[9]+"|"+output[10]+"|"+output[11]+"|"+output[12]+"|"+output[13]+"|"+output[14]+"|"+output[15]
            tanium.results.add(result)

if __name__ == '__main__':
    tanium.timeout_seconds = 3
    sensor_main()

